#' Summary of Categorical Variables
#'
#' 
#' @param data .
#' @param vars .
#' @param showConsole .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$overview} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$frequencies} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$clinicalSummary} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$reportSentences} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$assumptions} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$distribution} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$console} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$overview$asDF}
#'
#' \code{as.data.frame(results$overview)}
#'
#' @export
pyreportcat <- function(
    data,
    vars = NULL,
    showConsole = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("pyreportcat requires jmvcore to be installed (restart may be required)")

    if ( ! missing(vars)) vars <- jmvcore::resolveQuo(jmvcore::enquo(vars))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(vars), vars, NULL))

    for (v in vars) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- pyreportcatOptions$new(
        vars = vars,
        showConsole = showConsole)

    analysis <- pyreportcatClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

